// src/jsx/Register.jsx
import React, { useState } from "react";
import { createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import { auth, db, storage } from "../js/firebaseConfig";
import { doc, setDoc, serverTimestamp } from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";

export default function Register({ setScreen }) {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [senha2, setSenha2] = useState("");
  const [avatarFile, setAvatarFile] = useState(null);
  const [loading, setLoading] = useState(false);

  const cadastrar = async () => {
    if (!nome.trim()) return alert("Informe seu nome.");
    if (!email.trim()) return alert("Informe seu email.");
    if (senha.length < 6) return alert("Senha deve ter ao menos 6 caracteres.");
    if (senha !== senha2) return alert("Senhas não conferem.");

    setLoading(true);

    try {
      // 1) cria user no Auth
      const userCred = await createUserWithEmailAndPassword(auth, email, senha);
      const uid = userCred.user.uid;

      let avatarUrl = "";

      console.log("Avatar file (antes do upload):", avatarFile);

      // 2) faz upload se houver arquivo
      if (avatarFile) {
        // cria nome único do arquivo para evitar sobrescritas
        const fileName = `${Date.now()}_${avatarFile.name}`;
        const avatarRef = ref(storage, `avatars/${uid}/${fileName}`);

        await uploadBytes(avatarRef, avatarFile);
        avatarUrl = await getDownloadURL(avatarRef);
        console.log("Upload finalizado, URL:", avatarUrl);

        // 3) tenta atualizar profile no Auth (photoURL e displayName)
        try {
          await updateProfile(userCred.user, {
            displayName: nome,
            photoURL: avatarUrl
          });
        } catch (err) {
          console.warn("Não foi possível atualizar profile no Auth:", err);
          // não abortamos o cadastro por causa disso — salvaremos no Firestore abaixo
        }
      } else {
        // se não mandou avatar, ainda podemos definir displayName no Auth
        try {
          await updateProfile(userCred.user, {
            displayName: nome
          });
        } catch (err) {
          console.warn("Falha ao atualizar displayName no Auth:", err);
        }
      }

      // 4) salva dados no Firestore
      await setDoc(doc(db, "users", uid), {
        id: uid,
        nome,
        email,
        avatarUrl: avatarUrl || "",
        online: true,
        createdAt: serverTimestamp()
      });

      console.log("Documento criado em users:", uid);

      alert("Conta criada! Faça login.");
      setScreen("login");

    } catch (err) {
      console.error("ERRO NO REGISTER:", err);
      alert("Erro ao criar conta: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <h2>Criar Conta</h2>

      <input placeholder="Nome" value={nome} onChange={e => setNome(e.target.value)} />
      <input placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} />
      <input placeholder="Senha" type="password" value={senha} onChange={e => setSenha(e.target.value)} />
      <input placeholder="Confirmar senha" type="password" value={senha2} onChange={e => setSenha2(e.target.value)} />

      <div style={{ marginTop: 8 }}>
        <label>Avatar (opcional)</label>
        <input type="file" accept="image/*" onChange={e => setAvatarFile(e.target.files[0] || null)} />
      </div>

      <button onClick={cadastrar} disabled={loading}>
        {loading ? "Criando..." : "Cadastrar"}
      </button>

      <p style={{ marginTop: 20, cursor: "pointer" }} onClick={() => setScreen("login")}>
        Voltar ao Login
      </p>
    </div>
  );
}
